SELECT DATE_TRUNC('QUARTER', opened_date) AS quarter_start, city, APPROX_PERCENTILE(sqft, 0.9) AS sqft_p90, SORT_ARRAY(COLLECT_SET(region)) AS region_list, AVG(sqft) AS avg_sqft, SUM(sqft) FILTER (WHERE region = 'Central') AS central_total_sqft, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(DISTINCT id) AS distinct_ids FROM stores GROUP BY CUBE (DATE_TRUNC('QUARTER', opened_date), city) HAVING COUNT(DISTINCT id) >= 1 ORDER BY central_total_sqft DESC
